#!/usr/bin/env node
const sdk = require('./lyenv_sdk.js');

async function main() {
  await sdk.read_request();
  sdk.log('sdk_js_ok');
  sdk.respond_ok('');
}

main().catch((err) => {
  try { sdk.respond_error(err.message || String(err)); }
  catch { process.stderr.write(String(err) + '\n'); process.exit(1); }
});

#!/usr/bin/env node
const sdk = require('./lyenv_sdk.js');

async function main(){
  const req = await sdk.read_request();
  sdk.respond_ok((req.args||[]).join(' '));
}
main().catch(e=>sdk.respond_error(e.message||String(e)));
